from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[1]
def image(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
G=json.loads((R/'source/geometry-and-uv.json').read_text());G['body']=json.loads((R/'references/approved-machine-geometry.json').read_text())
images={p.name:image(p)for folder in ['review','exports']for p in (R/folder).glob('*.png')if 'review'not in p.name}
snapshots=[dict(id='inactive',label='未工作 · 暗灯',active=False,ghost=False),dict(id='active',label='工作 · 薄荷绿灯',active=True,ghost=False),dict(id='enabled-inactive',label='已开启 · 节点未工作',active=False,ghost=False,enabled=True),dict(id='zero-energy',label='余量0 · 不推断未工作原因',active=False,ghost=False,energy=0),dict(id='last-payment',label='支付后余量0 · 本刻仍工作',active=True,ghost=False,energy=0),dict(id='power-reference',label='供能失败灯 · 仅设计参考',active=False,ghost=False,mode='design_reference',failureReason='payment_rejected'),dict(id='ghost',label='安装预览 · 统一绿色',active=True,ghost=True)]
